/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { ConfinementScreen } from "../../src/confinement/ConfinementScreen.js";
import { EightfoldWayScreen } from "../../src/eightfold-way/EightfoldWayScreen.js";
import { HadronBuilderScreen } from "../../src/hadron-builder/HadronBuilderScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import ParticleZooColors from "../../src/ParticleZooColors.js";
import { ParticleZooPreferencesModel } from "../../src/preferences/ParticleZooPreferencesModel.js";
import { ReactionCourtScreen } from "../../src/reaction-court/ReactionCourtScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from particleZooQueryParameters.
  const simPreferences = new ParticleZooPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new HadronBuilderScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().hadronBuilderStringProperty,
      tandem: Tandem.ROOT.createTandem("hadronBuilderScreen"),
      backgroundColorProperty: ParticleZooColors.backgroundColorProperty,
    }),
    new EightfoldWayScreen({
      name: stringManager.getScreenNames().eightfoldWayStringProperty,
      tandem: Tandem.ROOT.createTandem("eightfoldWayScreen"),
      backgroundColorProperty: ParticleZooColors.backgroundColorProperty,
    }),
    new ConfinementScreen({
      name: stringManager.getScreenNames().confinementStringProperty,
      tandem: Tandem.ROOT.createTandem("confinementScreen"),
      backgroundColorProperty: ParticleZooColors.backgroundColorProperty,
    }),
    new ReactionCourtScreen({
      name: stringManager.getScreenNames().reactionCourtStringProperty,
      tandem: Tandem.ROOT.createTandem("reactionCourtScreen"),
      backgroundColorProperty: ParticleZooColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { ParticleZooColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
